import{_ as a,o as t,c as i,ae as s}from"./chunks/framework.BX6FPmO9.js";const g=JSON.parse('{"title":"Web Vitals panel (T-2026-115, Pillar 4)","description":"","frontmatter":{},"headers":[],"relativePath":"perf/vitals-panel.md","filePath":"perf/vitals-panel.md"}'),o={name:"perf/vitals-panel.md"};function l(n,e,r,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="web-vitals-panel-t-2026-115-pillar-4" tabindex="-1">Web Vitals panel (T-2026-115, Pillar 4) <a class="header-anchor" href="#web-vitals-panel-t-2026-115-pillar-4" aria-label="Permalink to &quot;Web Vitals panel (T-2026-115, Pillar 4)&quot;">​</a></h1><p>Local, offline-first Core Web Vitals — no backend, no analytics endpoint required.</p><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><ul><li><code>app/lib/analytics/web-vitals-reporter.ts</code> subscribes to <code>onLCP</code> / <code>onINP</code> / <code>onCLS</code> from <code>web-vitals</code> and always mirrors each metric into <code>app/lib/analytics/vitals-store.ts</code> (in-memory <code>Map</code> + <code>sessionStorage</code> mirror, tab-scoped).</li><li><code>/vitals</code> (<code>app/routes/vitals.tsx</code>) reads that store via <code>useSyncExternalStore</code> and renders the latest LCP/INP/CLS with their rating (<code>good</code> / <code>needs-improvement</code> / <code>poor</code>) and standard thresholds.</li><li>The event payload is a closed schema — <code>webVitalReportedEventSchema</code> in <code>packages/shared-contracts/src/analytics.contract.ts</code> (<code>name</code>, <code>value</code>, <code>rating</code>, <code>route</code>; <code>.strict()</code>, no free-form properties).</li></ul><h2 id="seeing-it-locally" tabindex="-1">Seeing it locally <a class="header-anchor" href="#seeing-it-locally" aria-label="Permalink to &quot;Seeing it locally&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><ol><li>Open <code>http://localhost:5173/</code>, click around a few routes (LCP/CLS finalize as the page settles; INP needs at least one interaction).</li><li>Open <code>http://localhost:5173/vitals</code> — the last known value per metric for this browser tab is shown live and updates as new metrics land.</li><li>Cross-reference with the measured, scripted numbers for the catalog dictionary virtualization work in <a href="./catalog-dictionary-measured.json"><code>docs/perf/catalog-dictionary-measured.json</code></a> (Playwright-driven DOM/heap/long-task capture, not live web-vitals).</li></ol><h2 id="optional-aggregate-p75-in-posthog" tabindex="-1">Optional: aggregate P75 in PostHog <a class="header-anchor" href="#optional-aggregate-p75-in-posthog" aria-label="Permalink to &quot;Optional: aggregate P75 in PostHog&quot;">​</a></h2><p>The local <code>/vitals</code> panel shows only <em>this tab&#39;s</em> latest sample per metric — useful for a live demo, not for a fleet-wide P75. To see an aggregate:</p><ol><li><p>Set <code>VITE_ANALYTICS_ENABLED=1</code> (and optionally <code>VITE_ANALYTICS_ENDPOINT</code>) so <code>web-vitals-reporter.ts</code> also POSTs each metric (see <code>labs/observability/POSTHOG.md</code>).</p></li><li><p>Bring up the local capture stub / PostHog compose:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> labs/observability/docker-compose.posthog.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div></li><li><p>Load several pages to accumulate samples, then view Web Vitals / Insights in PostHog (or the capture stub logs at <code>http://localhost:19000</code> for a quick sanity check that events are leaving the browser).</p></li></ol><h3 id="screenshot-placeholder" tabindex="-1">Screenshot placeholder <a class="header-anchor" href="#screenshot-placeholder" aria-label="Permalink to &quot;Screenshot placeholder&quot;">​</a></h3><p><em>No screenshot captured yet — this repo intentionally avoids checking in a live PostHog project screenshot until STOP-003 registration is resolved (see <code>labs/observability/POSTHOG.md</code>). When available, add it here as:</em></p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">![</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">PostHog Web Vitals P75</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">./posthog-web-vitals-p75.png</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div>',13)])])}const k=a(o,[["render",l]]);export{g as __pageData,k as default};
